//ggml: enable Vulkan shader debug info
GGML_VULKAN_SHADER_DEBUG_INFO:BOOL=OFF

//ggml: enable Vulkan validation
GGML_VULKAN_VALIDATE:BOOL=OFF

//ggml: enable vxe
GGML_VXE:BOOL=ON

//ggml: use WebGPU
GGML_WEBGPU:BOOL=OFF

//ggml: enable WebGPU profiling (CPU)
GGML_WEBGPU_CPU_PROFILE:BOOL=OFF

//ggml: enable WebGPU debug output
GGML_WEBGPU_DEBUG:BOOL=OFF

//ggml: enable WebGPU profiling (GPU)
GGML_WEBGPU_GPU_PROFILE:BOOL=OFF

//ggml: use JSPI for WebGPU
GGML_WEBGPU_JSPI:BOOL=ON

//ggml: enable xtheadvector
GGML_XTHEADVECTOR:BOOL=OFF

//ggml: use zDNN
GGML_ZDNN:BOOL=OFF

//ggml: use ZenDNN
GGML_ZENDNN:BOOL=OFF

//Path to a program.
GITCOMMAND:FILEPATH=GITCOMMAND-NOTFOUND

//Path to a program.
GIT_EXE:FILEPATH=GIT_EXE-NOTFOUND

//Git command line client
GIT_EXECUTABLE:FILEPATH=GIT_EXECUTABLE-NOTFOUND

//llama: enable all compiler warnings
LLAMA_ALL_WARNINGS:BOOL=ON

//llama: enable all compiler warnings in 3rd party libs
LLAMA_ALL_WARNINGS_3RD_PARTY:BOOL=OFF

//Location of binary  files
LLAMA_BIN_INSTALL_DIR:PATH=bin

//llama: build the unified binary
LLAMA_BUILD_APP:BOOL=OFF

//llama: build common utils library
LLAMA_BUILD_COMMON:BOOL=ON

//llama: build examples
LLAMA_BUILD_EXAMPLES:BOOL=ON

//llama: dev build
LLAMA_BUILD_IS_DEV:BOOL=ON

//llama: build tools/mtmd library standalone
LLAMA_BUILD_MTMD:BOOL=OFF

//llama: build server example
LLAMA_BUILD_SERVER:BOOL=ON

//llama: build tests
LLAMA_BUILD_TESTS:BOOL=ON

//llama: build tools
LLAMA_BUILD_TOOLS:BOOL=ON

//llama: build the embedded Web UI for server
LLAMA_BUILD_UI:BOOL=OFF

//llama: enable -Werror flag
LLAMA_FATAL_WARNINGS:BOOL=OFF

//Location of header  files
LLAMA_INCLUDE_INSTALL_DIR:PATH=include

//Location of library files
LLAMA_LIB_INSTALL_DIR:PATH=lib64

//llama-common: include LLGuidance library for structured output
// in common utils
LLAMA_LLGUIDANCE:BOOL=OFF

//llama: use openssl to support HTTPS
LLAMA_OPENSSL:BOOL=OFF

//llama: enable address sanitizer
LLAMA_SANITIZE_ADDRESS:BOOL=OFF

//llama: enable thread sanitizer
LLAMA_SANITIZE_THREAD:BOOL=OFF

//llama: enable undefined sanitizer
LLAMA_SANITIZE_UNDEFINED:BOOL=OFF

//llama-common: use subprocess, required by server tools and server
// router mode
LLAMA_SUBPROCESS:BOOL=ON

//llama: install tests
LLAMA_TESTS_INSTALL:BOOL=ON

//llama: install tools
LLAMA_TOOLS_INSTALL:BOOL=ON

//Apply gzip compress to assets to save bandwidth
LLAMA_UI_GZIP:BOOL=ON

//Hugging Face bucket name for prebuilt UI assets
LLAMA_UI_HF_BUCKET:STRING=ggml-org/llama-ui

//llama: use prebuilt UI from HF Bucket when available
LLAMA_USE_PREBUILT_UI:BOOL=OFF

//Use system libggml
LLAMA_USE_SYSTEM_GGML:BOOL=OFF

//llama: use 64-bit memory in WASM builds
LLAMA_WASM_MEM64:BOOL=ON

//Command to build the project
MAKECOMMAND:STRING=/share/apps/cmake/3.28.1/bin/cmake --build . --config "${CTEST_CONFIGURATION_TYPE}"

//Path to the memory checking command, used for memory error detection.
MEMORYCHECK_COMMAND:FILEPATH=MEMORYCHECK_COMMAND-NOTFOUND

//File that contains suppressions for the memory checker
MEMORYCHECK_SUPPRESSIONS_FILE:FILEPATH=

//enable video support in mtmd (requires ffmpeg binary in PATH)
MTMD
